# median universe, used only as a smooth regime conditioner.
cs=r.rolling(20,min_periods=15).sum(); med=cs.median(axis=1)
defstate=((cs.get('XAU')-med)+(cs.get('US10Y')-med)+(cs.get('CN10Y')-med))/3
state=np.tanh(defstate/(r.rolling(20,min_periods=15).std().median(axis=1)+1e-6))
