# positive relative trend; this remains a long-only ranking factor.
rel=mom.sub(mom.median(axis=1),axis=0)/(v20+1e-6)
f=rel*(1-0.30*state)+0.20*state*(cs.sub(cs.median(axis=1),axis=0)/(v20+1e-6))-.20*short/(v20+1e-6)
f=f.sub(f.median(axis=1),axis=0).shift(1)
rows=[]
