raw=(0.55*m60+0.45*m120)/(v60+1e-8)-.40*(m20-m60/3).abs()/(v60+1e-8)
f=(-raw).shift(1); f.to_csv('scripts/miner_2_20310904_trend_exhaustion_contrarian_signal.csv')
