import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y'];cut=pd.Timestamp('2032-02-04');raw={}
for s in U:
 d=get_stock_daily_data(s,days=5000)
 if d is not None and len(d):
  d=d.copy();d.date=pd.to_datetime(d.date);d=d[d.date<=cut].sort_values('date');raw[s]=d.set_index('date').close
px=pd.DataFrame(raw).sort_index();r=np.log(px).diff();
# Relative 10-day pullback, scaled by downside volatility, gated to assets above their 120d median trend.
med=r.rolling(30,min_periods=20).apply(lambda x: np.sqrt(np.mean(np.minimum(x,0)**2)),raw=True)
rel=np.log(px/px.shift(10)).sub(np.log(px/px.shift(10)).median(axis=1),axis=0)
trend=np.log(px/px.rolling(120,min_periods=80).median())
f=(-rel/(med*np.sqrt(10)+1e-9))*((np.tanh(trend*2)+1)/2);f=f.shift(1)
def run(h):
 vals=[];ns=[];turn=[];fr=np.log(px.shift(-h)/px)
 for i,dt in enumerate(f.index):
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8: vals.append((dt,z.iloc[:,0].corr(z.iloc[:,1],method='spearman')));ns.append(len(z))
  if i:
   q=pd.concat([f.iloc[i-1],f.iloc[i]],axis=1).dropna()
   if len(q)>=8: turn.append(q.iloc[:,0].rank().sub(q.iloc[:,1].rank()).abs().mean()/len(q))
 s=pd.Series(dict(vals));return s,np.mean(ns),np.mean(turn)
for h in [1,5,10,20]:
 s,n,t=run(h);print('h',h,'dates',len(s),'avg_n',n,'coverage',n/15,'IC',s.mean(),'ICIR',s.mean()/s.std(),'hit',np.mean(s>0),'turn',t)
s,n,t=run(10)
for a,b in [('2020','2025'),('2026','2028'),('2029','2030'),('2031','2032')]:
 q=s[(s.index>=a)&(s.index<=b)];print('regime',a,b,'dates',len(q),'IC',q.mean(),'ICIR',q.mean()/q.std() if len(q)>1 else np.nan)
print('coverage dates',len(s),'assets',len(px.columns),'last',s.index.max())
# signal artifact for deterministic provenance
out=f.stack().rename('signal').reset_index();out.columns=['date','symbol','signal'];out.to_csv('scripts/miner_2_20320205_downside_relative_reversal_signal.csv',index=False);print('artifact_rows',len(out))

